import React, { useEffect, useState, useCallback } from "react";
import axios from "axios";
import {
  FaBrain,
  FaClock,
  FaExclamationTriangle,
  FaCalendarCheck,
  FaBookOpen
} from "react-icons/fa";

function SmartPlannerAdvanced() {
  const userId = localStorage.getItem("user_id");

  const [planner, setPlanner] = useState({
    today: "",
    weakest_course: "",
    recommended_hours_today: 0,
    today_tasks_count: 0,
    today_tasks: [],
    all_tasks: []
  });

  const fetchPlanner = useCallback(() => {
    axios
      .get(`http://127.0.0.1:8000/smart-plan-advanced/${userId}`)
      .then((res) => setPlanner(res.data))
      .catch((err) => console.error(err));
  }, [userId]);

  useEffect(() => {
   fetchPlanner();

   const handlePlannerUpdate = () => {
    fetchPlanner();
  };

  window.addEventListener("plannerUpdated", handlePlannerUpdate);

  return () => {
    window.removeEventListener("plannerUpdated", handlePlannerUpdate);
  };
}, [fetchPlanner]);
 

  const getPriorityStyle = (priority) => {
    if (priority === "High") {
      return {
        background: "#ffebee",
        color: "#c62828",
        border: "1px solid #ef9a9a"
      };
    }
    if (priority === "Medium") {
      return {
        background: "#fff3e0",
        color: "#ef6c00",
        border: "1px solid #ffcc80"
      };
    }
    return {
      background: "#e8f5e9",
      color: "#2e7d32",
      border: "1px solid #a5d6a7"
    };
  };

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" }}>
        <h2 style={{ color: "#6a1b9a", margin: 0 }}>Smart Planner</h2>

        <button
          onClick={fetchPlanner}
          style={{
            background: "#7b1fa2",
            color: "#fff",
            border: "none",
            padding: "10px 16px",
            borderRadius: "10px",
            cursor: "pointer"
          }}
        >
          Refresh Planner
        </button>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))",
          gap: "18px",
          marginBottom: "25px"
        }}
      >
        <div style={summaryCard("#ede7f6")}>
          <div style={iconBox("#7b1fa2")}><FaBrain /></div>
          <h3 style={cardTitle}>Weakest Subject</h3>
          <p style={cardValue}>{planner.weakest_course || "N/A"}</p>
        </div>

        <div style={summaryCard("#e3f2fd")}>
          <div style={iconBox("#1565c0")}><FaClock /></div>
          <h3 style={cardTitle}>Recommended Hours</h3>
          <p style={cardValue}>{planner.recommended_hours_today} hrs</p>
        </div>

        <div style={summaryCard("#fff3e0")}>
          <div style={iconBox("#ef6c00")}><FaExclamationTriangle /></div>
          <h3 style={cardTitle}>Today's Tasks</h3>
          <p style={cardValue}>{planner.today_tasks_count}</p>
        </div>

        <div style={summaryCard("#e8f5e9")}>
          <div style={iconBox("#2e7d32")}><FaCalendarCheck /></div>
          <h3 style={cardTitle}>Today</h3>
          <p style={cardValue}>{planner.today || "--"}</p>
        </div>
      </div>

      <div style={panelStyle}>
        <h3 style={headingStyle}>Today's Smart Plan</h3>

        {planner.today_tasks.length === 0 ? (
          <p>No tasks for today.</p>
        ) : (
          planner.today_tasks.map((task, index) => (
            <div key={index} style={taskCard}>
              <div style={{ display: "flex", justifyContent: "space-between", gap: "15px", flexWrap: "wrap" }}>
                <div>
                  <h4 style={{ margin: "0 0 6px 0", color: "#222" }}>{task.course_title}</h4>
                  <p style={{ margin: "0 0 6px 0", color: "#666" }}>
                    Subject Code: {task.subject_code}
                  </p>
                  <p style={{ margin: "0 0 6px 0" }}>
                    <strong>Task:</strong> {task.task}
                  </p>
                  <p style={{ margin: "0 0 6px 0" }}>
                    <strong>Study Time:</strong> {task.daily_hours} hrs
                  </p>
                  <p style={{ margin: 0 }}>
                    <strong>Deadline:</strong> {task.deadline || "No deadline"}
                  </p>
                </div>

                <div>
                  <span style={{ ...priorityBadge, ...getPriorityStyle(task.priority) }}>
                    {task.priority}
                  </span>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      <div style={{ ...panelStyle, marginTop: "25px" }}>
        <h3 style={headingStyle}>Upcoming Study Schedule</h3>

        {planner.all_tasks.length === 0 ? (
          <p>No smart tasks generated.</p>
        ) : (
          planner.all_tasks.map((task, index) => (
            <div key={index} style={scheduleRow}>
              <div style={{ minWidth: "120px", fontWeight: "bold", color: "#6a1b9a" }}>
                {task.date}
              </div>

              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: "600" }}>
                  <FaBookOpen style={{ marginRight: "8px", color: "#7b1fa2" }} />
                  {task.course_title}
                </div>
                <div style={{ color: "#555", marginTop: "4px" }}>
                  {task.task}
                </div>
                <div style={{ color: "#777", marginTop: "4px", fontSize: "14px" }}>
                  Progress: {task.progress_percent}% | Study: {task.daily_hours} hrs
                </div>
              </div>

              <div>
                <span style={{ ...priorityBadge, ...getPriorityStyle(task.priority) }}>
                  {task.priority}
                </span>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

const summaryCard = (bg) => ({
  background: bg,
  borderRadius: "18px",
  padding: "20px",
  boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
});

const iconBox = (bg) => ({
  width: "42px",
  height: "42px",
  borderRadius: "12px",
  background: bg,
  color: "#fff",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  marginBottom: "12px",
  fontSize: "18px"
});

const cardTitle = {
  margin: "0 0 8px 0",
  fontSize: "16px",
  color: "#444"
};

const cardValue = {
  margin: 0,
  fontSize: "22px",
  fontWeight: "bold",
  color: "#222"
};

const panelStyle = {
  background: "#fff",
  borderRadius: "18px",
  padding: "20px",
  boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
};

const headingStyle = {
  marginBottom: "18px",
  color: "#6a1b9a"
};

const taskCard = {
  border: "1px solid #eee",
  borderRadius: "14px",
  padding: "16px",
  background: "#fafafa",
  marginBottom: "14px"
};

const scheduleRow = {
  display: "flex",
  gap: "18px",
  alignItems: "center",
  border: "1px solid #eee",
  borderRadius: "12px",
  padding: "14px",
  background: "#fafafa",
  marginBottom: "12px"
};

const priorityBadge = {
  padding: "6px 12px",
  borderRadius: "999px",
  fontSize: "13px",
  fontWeight: "bold"
};

export default SmartPlannerAdvanced;
